<?php

namespace App\Services\Physio\Demo;

/**
 * Presentation-ready bilingual content for the curated physiotherapy demo.
 *
 * This class deliberately uses preliminary, non-diagnostic language. It is a
 * presentation layer only and does not replace clinical examination.
 */
final class PhysioDemoLocalizedContent
{
    /**
     * @param  array<string, mixed>  $case
     * @return array<string, mixed>
     */
    public function forCase(array $case, string $language): array
    {
        return strtolower($language) === 'ar'
            ? $this->arabic($case)
            : $this->english($case);
    }

    /**
     * @param  array<string, mixed>  $case
     * @return array<string, mixed>
     */
    private function english(array $case): array
    {
        $urgent = strtoupper((string) ($case['escalation_level'] ?? 'LOW')) === 'URGENT';
        $pattern = $this->text($case['expected_clinical_pattern'] ?? null);
        $impression = $this->text($case['initial_clinical_impression'] ?? null);
        $activity = $this->text($case['activity_advice'] ?? null);

        return [
            'title' => $pattern !== '' ? $pattern : $this->englishTitle($case),
            'subtitle' => 'Initial assessment based on reported symptoms and entered information',
            'clinical_impression' => $impression !== ''
                ? 'A preliminary clinical impression is that '.$this->lowerFirst($impression)
                : 'The reported features may be consistent with a musculoskeletal presentation that requires clinical correlation.',
            'key_findings' => $this->englishFindings($case),
            'self_management' => [
                'today' => $activity !== '' ? $this->sentences($activity) : ['Keep activity within a comfortable, symptom-guided range.'],
                'next_days' => $urgent
                    ? ['Follow the advice of the urgent medical assessment team before starting rehabilitation.']
                    : ['Progress activity gradually if symptoms remain stable.', 'Arrange review if symptoms do not improve or begin to worsen.'],
            ],
            'avoid' => $this->stringList($case['avoid'] ?? []),
            'red_flags' => $this->stringList($case['red_flags'] ?? []),
            'next_step' => $this->text($case['next_step'] ?? null) ?: 'Monitor progress and seek a physiotherapy assessment if symptoms persist.',
            'evidence_basis' => $this->evidenceCategories($this->text($case['evidence_basis'] ?? null)),
            'medical_priority_message' => $urgent
                ? 'Urgent medical assessment is the priority. Do not use exercise as the primary response until a clinician has assessed the warning features.'
                : null,
        ];
    }

    /**
     * @param  array<string, mixed>  $case
     * @return array<string, mixed>
     */
    private function arabic(array $case): array
    {
        $id = strtoupper($this->text($case['case_id'] ?? null));
        $content = $this->arabicCases()[$id] ?? $this->arabicFallback($case);
        $urgent = strtoupper((string) ($case['escalation_level'] ?? 'LOW')) === 'URGENT';

        return [
            'title' => $content['title'],
            'subtitle' => 'التقييم السريري الأولي بناءً على الأعراض المبلغ عنها والمعلومات المدخلة',
            'clinical_impression' => $content['impression'],
            'key_findings' => $this->arabicFindings($content['findings']),
            'self_management' => [
                'today' => $content['today'],
                'next_days' => $content['next_days'],
            ],
            'avoid' => $content['avoid'],
            'red_flags' => $content['red_flags'],
            'next_step' => $content['next_step'],
            'evidence_basis' => ['إرشادات APTA/JOSPT', 'مبادئ التأهيل الحركي المبني على الدليل', 'إرشادات السلامة والفرز السريري'],
            'medical_priority_message' => $urgent
                ? 'الأولوية هي إجراء تقييم طبي عاجل. لا تُعد التمارين الحل الأساسي قبل فحص علامات الخطر والحصول على توجيه طبي واضح.'
                : null,
        ];
    }

    /**
     * Every supported demo identifier is intentionally explicit here.
     *
     * @return array<string, array<string, mixed>>
     */
    private function arabicCases(): array
    {
        return [
            'PHYS-01' => $this->arCase('ألم الرقبة المرتبط بالعمل المكتبي', 'انطباع أولي: الأعراض متوافقة مع ألم رقبة ميكانيكي قد يرتبط بالجلوس الطويل ووضعية الرأس أثناء استخدام الحاسوب.', ['تيبس وألم موضعيان دون أعراض عصبية بالطرف العلوي', 'تزداد الأعراض مع ثبات الرأس للأمام', 'تتحسن مؤقتاً مع فواصل الحركة'], ['غيّر وضعيتك وخذ فاصل حركة كل 30–45 دقيقة', 'اضبط ارتفاع الشاشة وأرخِ الكتفين'], ['ابدأ تمارين لطيفة للرقبة ولوحي الكتف', 'زِد مدة النشاط تدريجياً حسب الاستجابة'], ['الثبات الطويل بوضعية الرأس للأمام', 'الأحمال العلوية الثقيلة مؤقتاً'], ['ضعف جديد بالذراع', 'خدر أو تنميل مستمر', 'صداع شديد مع حمى'], 'استمر بالتدبير المحافظ من أسبوع إلى أسبوعين، واطلب تقييماً إذا استمر الألم أو ظهرت أعراض عصبية.'),
            'PHYS-02' => $this->arCase('ألم الرقبة مع صداع مرتبط بها', 'يبدو النمط أقرب إلى ألم رقبة ميكانيكي مصحوب بسمات صداع منشؤه الرقبة، مع ضرورة استبعاد الأسباب الأخرى سريرياً.', ['الصداع يرتبط بحركة الرقبة أو وضعيتها', 'وجود تيبس موضعي بالرقبة', 'لا تكفي الأعراض وحدها لتأكيد سبب الصداع'], ['خفف الوضعيات المستفزة واستخدم حركة رقبة لطيفة', 'نظّم فترات العمل والنوم والترطيب'], ['راقب نمط الصداع واستجابة الرقبة للحركة', 'رتب تقييماً إذا تكرر الصداع'], ['المناورات القوية للرقبة', 'الاستمرار في وضعية تزيد الصداع'], ['صداع مفاجئ غير معتاد', 'اضطراب رؤية أو كلام', 'ضعف أو اختلال توازن'], 'يوصى بتقييم علاج طبيعي عند استمرار الأعراض، وتقييم طبي سريع عند أي تغير عصبي أو صداع غير معتاد.'),
            'PHYS-03' => $this->arCase('تيبس الرقبة بعد النوم', 'الانطباع السريري الأولي متوافق مع تيبس ميكانيكي عابر قد يرتبط بوضعية نوم غير مريحة.', ['بدأ التيبس بعد الاستيقاظ', 'الأعراض موضعية دون انتشار عصبي', 'الحركة اللطيفة قد تقلل التيبس'], ['حرّك الرقبة بلطف ضمن المجال المريح', 'استخدم دعماً مناسباً للرأس أثناء النوم'], ['عد تدريجياً للنشاط المعتاد', 'راجع وضعية الوسادة إذا تكرر الأمر'], ['تمطيط الرقبة بعنف', 'النوم مع التواء شديد للرقبة'], ['ألم شديد متزايد', 'حمى مع تيبس شديد', 'ضعف أو خدر بالأطراف'], 'راقب التحسن خلال عدة أيام واطلب تقييماً إذا لم يتحسن التيبس أو ظهرت علامات تستدعي الانتباه.'),
            'PHYS-04' => $this->arCase('شد الرقبة المرتبط باستخدام الهاتف', 'قد ترتبط الأعراض بإجهاد عضلي ووضعية رقبة ثابتة أثناء استخدام الهاتف لفترات طويلة.', ['الشد يتزايد مع انحناء الرأس للهاتف', 'لا توجد سمات عصبية مذكورة', 'تعديل الوضعية وفواصل الحركة عوامل مهمة'], ['ارفع الهاتف إلى مستوى أقرب للعين', 'خذ فواصل قصيرة ومتكررة للحركة'], ['أضف تمارين تحكم وضعي خفيفة', 'قلل مدة الاستخدام المتواصل'], ['انحناء الرأس لفترات طويلة', 'التمرين الذي يسبب ألماً حاداً'], ['ضعف بالذراع', 'تنميل مستمر', 'دوار أو صداع شديد جديد'], 'ابدأ بتعديل الحمل والوضعية، واستشر مختصاً إذا بقيت الأعراض أو تكررت بصورة مؤثرة.'),
            'PHYS-05' => $this->arCase('ألم الرقبة مع خدر بالذراع', 'انطباع أولي: الأعراض قد ترتبط بتهيّج عصبي من منطقة الرقبة، وتحتاج فحصاً سريرياً لتحديد السبب ودرجة التأثر.', ['ألم الرقبة مصحوب بخدر يمتد إلى الذراع', 'وجود أعراض عصبية يرفع أولوية التقييم', 'يلزم فحص القوة والإحساس والمنعكسات'], ['خفف الوضعيات التي تزيد انتشار الأعراض', 'حافظ على الرقبة في وضع مريح'], ['رتب تقييماً سريرياً قريباً', 'لا تبدأ تمارين مقاومة قبل تقييم الأعراض العصبية'], ['التحميل الثقيل فوق الرأس', 'مناورات الرقبة القوية'], ['ضعف متزايد بالذراع أو اليد', 'فقدان إحساس مستمر', 'اضطراب مشي أو تحكم بالمثانة'], 'احجز تقييماً طبياً أو علاجاً طبيعياً قريباً، وبصورة عاجلة إذا كان الضعف يتقدم.'),
            'PHYS-06' => $this->arCase('ألم أسفل الظهر بعد الرفع', 'الأعراض تبدو أقرب إلى ألم ميكانيكي حاد بأسفل الظهر بعد الرفع، دون أن يمثل ذلك تشخيصاً نهائياً.', ['بداية مرتبطة بحركة رفع', 'الألم يتأثر بالحركة والحمل', 'الحركة التدريجية أفضل عادة من الراحة الطويلة'], ['استمر بالمشي الخفيف وتجنب الراحة التامة', 'استخدم حركات مريحة ومتدرجة'], ['زد النشاط اليومي تدريجياً', 'تدرّب لاحقاً على أسلوب رفع مناسب'], ['الرفع الثقيل والالتواء المتزامن', 'الراحة في السرير لفترة طويلة'], ['خدر بمنطقة السرج', 'تغير التحكم بالمثانة أو الأمعاء', 'ضعف متزايد بالساق'], 'راقب التحسن خلال الأيام التالية واطلب تقييماً إذا اشتد الألم أو ظهرت علامات عصبية.'),
            'PHYS-07' => $this->arCase('ألم أسفل الظهر مع الجلوس الطويل', 'انطباع أولي متوافق مع ألم ميكانيكي تحت حاد قد يرتبط بالجلوس المطوّل وقلة تنويع الحركة.', ['الألم يزداد مع الجلوس المطول', 'النمط موضعي دون علامات عصبية واضحة', 'فواصل الحركة قد تخفف الأعراض'], ['بدّل بين الجلوس والوقوف والمشي', 'خذ فاصل حركة كل 30–45 دقيقة'], ['أضف نشاطاً هوائياً خفيفاً وتمارين تحمل تدريجية', 'زد مدة الجلوس تدريجياً'], ['الجلوس المتواصل لساعات', 'الخمول الكامل'], ['ألم ممتد مع ضعف', 'خدر بمنطقة السرج', 'اضطراب التحكم بالمثانة أو الأمعاء'], 'استمر بالتدرج الحركي واطلب تقييماً إذا لم يتحسن الوضع خلال أسبوعين.'),
            'PHYS-08' => $this->arCase('ألم أسفل الظهر الممتد إلى الساق', 'قد يرتبط النمط بتهيّج جذور عصبية أو ألم جذري، ويستلزم فحصاً سريرياً لتقييم الوظيفة العصبية.', ['امتداد الأعراض من الظهر إلى الساق', 'قد تتغير الأعراض مع وضعيات العمود الفقري', 'فحص القوة والإحساس ضروري'], ['تجنب الوضعيات التي تزيد انتشار الألم', 'حافظ على حركة خفيفة ضمن الحدود المقبولة'], ['رتب تقييماً سريرياً قريباً', 'اتبع برنامجاً موجهاً بعد الفحص'], ['التمطيط العنيف للعصب', 'رفع الأوزان الثقيلة'], ['ضعف متزايد بالساق', 'خدر بمنطقة السرج', 'تغير التحكم بالمثانة أو الأمعاء'], 'يوصى بتقييم سريري قريب، وعاجل فوراً عند ظهور ضعف متقدم أو أعراض المثانة أو الأمعاء.'),
            'PHYS-09' => $this->arCase('ألم أسفل الظهر المزمن', 'الانطباع الأولي يبدو أقرب إلى ألم أسفل ظهر غير نوعي مستمر قد يتأثر بالحمل البدني والنوم والتوتر ومستوى النشاط.', ['استمرار الأعراض مدة طويلة', 'تذبذب الألم مع النشاط اليومي', 'الوظيفة والتدرج أهم من ملاحقة الألم وحده'], ['حافظ على نشاط يومي منتظم ومحتمل', 'اختر تمارين بسيطة يمكنك الاستمرار عليها'], ['زد القوة والتحمل تدريجياً', 'تابع النوم وإدارة الحمل والتعافي'], ['الخمول خوفاً من الحركة', 'الزيادات المفاجئة في الحمل'], ['فقدان وزن غير مفسر', 'حمى أو ألم ليلي متفاقم', 'تغير عصبي جديد'], 'ضع خطة تأهيل تدريجية مع مختص إذا كان الألم يحد الوظيفة أو لا يتحسن.'),
            'PHYS-10' => $this->arCase('ألم شديد بأسفل الظهر بعد سقوط', 'الأعراض بعد السقوط قد ترتبط بإصابة تحتاج تقييماً طبياً لاستبعاد إصابة عظمية أو عصبية مهمة.', ['وجود رض مباشر أو سقوط', 'شدة الألم تستدعي الحذر', 'القدرة على الحركة والحالة العصبية تحتاجان فحصاً'], ['قلل الحركة المؤلمة وحافظ على وضع آمن', 'اطلب تقييماً طبياً قريباً'], ['استأنف الحركة فقط وفق نتيجة التقييم', 'اتبع تعليمات الفريق المعالج'], ['الرفع أو التمرين القوي', 'تجاهل ازدياد الألم بعد الرض'], ['ضعف أو خدر جديد', 'عدم القدرة على المشي', 'مشكلات المثانة أو الأمعاء'], 'يُنصح بتقييم طبي سريع، خاصة عند الألم الشديد أو صعوبة الحركة أو أي علامة عصبية.'),
            'PHYS-11' => $this->arCase('ألم الكتف مع رفع الذراع', 'يبدو النمط أقرب إلى ألم كتف مرتبط بالحمل فوق مستوى الرأس، وقد يتوافق مع حساسية أنسجة الكفة المدورة.', ['الألم يظهر مع النشاط فوق الرأس', 'الحمل المتكرر عامل مهيج', 'الحركة والقوة تحتاجان تقييماً وظيفياً'], ['خفف حجم النشاط فوق الرأس', 'حافظ على حركة مريحة للكتف'], ['ابدأ تقوية تدريجية للكفة ولوح الكتف', 'أعد الحمل على مراحل'], ['الرفع المتكرر المؤلم', 'الوصول القسري لنهاية المدى'], ['ضعف مفاجئ واضح', 'تشوه بعد إصابة', 'خدر مستمر بالذراع'], 'ابدأ بإدارة الحمل واطلب تقييماً إذا استمر الألم أو أثر في النوم والوظيفة.'),
            'PHYS-12' => $this->arCase('ألم وضعف الكتف بعد زيادة التدريب', 'قد يرتبط الألم والضعف بزيادة مفاجئة في الحمل التدريبي، مع ضرورة فحص الكتف لاستبعاد إصابة أكبر.', ['ظهور الأعراض بعد زيادة الحمل', 'وجود ضعف وظيفي مع الألم', 'التعافي يحتاج خفض الحمل ثم إعادة بنائه'], ['أوقف التمارين التي تزيد الألم بوضوح', 'حافظ على حركة خفيفة غير مؤلمة'], ['رتب تقييماً للقوة والحركة', 'عد للأحمال تدريجياً بعد تحسن التحكم'], ['اختبار الأوزان القصوى', 'التدريب خلال الضعف المتزايد'], ['فقدان مفاجئ للقوة', 'ألم شديد بعد صوت فرقعة', 'تشوه أو تورم كبير'], 'يوصى بتقييم قريب إذا استمر الضعف، وبشكل أسرع إذا كان فقدان القوة مفاجئاً.'),
            'PHYS-13' => $this->arCase('ألم مقدمة الكتف بعد تمارين الدفع', 'انطباع أولي: الأعراض قد ترتبط بتحميل مقدمة الكتف أثناء تمارين الدفع، وتحتاج ضبط التقنية والحجم التدريبي.', ['الألم مرتبط بتمارين الضغط', 'موضع الألم أمام الكتف', 'الجرعة والتقنية عاملان قابلان للتعديل'], ['خفف الوزن أو المدى المؤلم', 'استخدم قبضة ووضع كتف مريحين'], ['أعد تمارين الدفع بجرعة أقل', 'وازن التدريب بتمارين سحب وتحكم لوح الكتف'], ['النزول العميق المؤلم', 'الزيادة السريعة في الوزن'], ['ضعف مفاجئ', 'كدمة أو تشوه', 'ألم ليلي شديد متزايد'], 'عدّل التدريب واطلب تقييماً إذا لم يتحسن الألم خلال أسبوع إلى أسبوعين.'),
            'PHYS-14' => $this->arCase('ألم جانب الكتف ليلاً', 'الأعراض متوافقة مبدئياً مع ألم كتف مرتبط بالحمل وقد يتضمن حساسية الكفة المدورة، لكن يلزم الفحص للتأكيد.', ['ألم بالجانب الخارجي للكتف', 'الانزعاج الليلي أو عند الاستلقاء على الجانب', 'الحركة فوق الرأس قد تزيد الأعراض'], ['تجنب النوم مباشرة على الكتف المؤلم', 'ادعم الذراع بوسادة وحافظ على حركة لطيفة'], ['ابدأ تقوية منخفضة الحمل', 'زد الاستخدام اليومي حسب تحمل الأعراض'], ['الاستلقاء الطويل على الجانب المؤلم', 'الحركات المتكررة المؤلمة فوق الرأس'], ['ضعف متزايد', 'احمرار وسخونة مع حمى', 'ألم شديد بعد إصابة'], 'رتب تقييماً إذا استمر الألم الليلي أو ظهرت خسارة واضحة في القوة أو الحركة.'),
            'PHYS-15' => $this->arCase('ألم وضعف شديد بالكتف بعد سقوط', 'قد تمثل الأعراض إصابة رضّية مهمة بالكتف، ويجب استبعاد كسر أو خلع أو تمزق كبير بالفحص والتصوير عند الحاجة.', ['السقوط سبب مباشر للأعراض', 'الألم والضعف شديدان', 'الرض قد يحتاج تصويراً طبياً'], ['ثبّت الذراع في وضع مريح مؤقتاً', 'اطلب تقييماً طبياً سريعاً'], ['ابدأ الحركة فقط بعد توجيه طبي', 'اتبع خطة التأهيل بعد استبعاد الإصابة الخطرة'], ['محاولة رد المفصل ذاتياً', 'تمارين المقاومة قبل التقييم'], ['تشوه واضح', 'خدر أو برودة باليد', 'عدم القدرة على تحريك الذراع'], 'اطلب تقييماً طبياً عاجلاً في اليوم نفسه، وخاصة مع التشوه أو فقدان الإحساس أو الحركة.'),
