            'PHYS-17' => $this->arCase('ألم خفيف بالكتف بعد زيادة التدريب', 'قد يرتبط الألم الخفيف بزيادة الحمل التدريبي أسرع من قدرة الأنسجة الحالية على التعافي.', ['الأعراض بدأت بعد زيادة التدريب', 'الشدة خفيفة دون ضعف كبير مذكور', 'خفض الحمل المؤقت قد يسمح بالتعافي'], ['قلل الحجم أو الشدة مؤقتاً', 'حافظ على تمارين لا تثير الألم'], ['أعد الحمل بزيادات صغيرة', 'راقب الاستجابة خلال 24 ساعة'], ['التدريب حتى الألم الشديد', 'الزيادات الكبيرة المتتالية'], ['ضعف واضح', 'ألم ليلي متصاعد', 'تورم أو تشوه بعد إصابة'], 'عدّل الحمل لمدة عدة أيام واطلب تقييماً إذا لم يظهر تحسن أو زادت الأعراض.'),
            'PHYS-18' => $this->arCase('ألم الكتف مع أعراض عصبية باليد', 'قد ترتبط الأعراض بتهيّج عصبي من الرقبة أو الطرف العلوي، ولا ينبغي افتراض أن مصدرها الكتف وحده.', ['ألم الكتف مصحوب بتنميل أو خدر باليد', 'توزع الأعراض العصبية يساعد في تحديد المصدر', 'فحص الرقبة والقوة والإحساس مطلوب'], ['تجنب الوضعيات التي تزيد الخدر', 'حافظ على الطرف في وضع مريح'], ['رتب فحصاً سريرياً قريباً', 'ابدأ التأهيل بعد تحديد مصدر الأعراض'], ['التحميل الثقيل', 'تمطيط الأعصاب بعنف'], ['ضعف متزايد باليد', 'فقدان إحساس مستمر', 'اختلال مشي أو أعراض بكلا الطرفين'], 'احصل على تقييم قريب، وعاجل إذا ظهر ضعف متقدم أو فقدان مستمر للإحساس.'),
