            'PHYS-30' => $this->arCase('ألم الكعب مع الخطوات الصباحية', 'يبدو النمط أقرب إلى ألم اللفافة الأخمصية المرتبط بالحمل، خاصة مع ألم الخطوات الأولى صباحاً.', ['الألم أشد مع أول خطوات الصباح', 'موضعه أسفل الكعب', 'التحميل والمرونة والحذاء عوامل مؤثرة'], ['استخدم حذاء داعماً وتجنب المشي حافياً طويلاً', 'نفّذ حركة لطيفة للكاحل قبل الوقوف'], ['ابدأ تمارين تدريجية للقدم وربلة الساق', 'زد المشي حسب الاستجابة'], ['الزيادات الكبيرة في المشي أو الجري', 'الضغط المؤلم المتكرر على الكعب'], ['تورم واحمرار شديدان', 'خدر أو حرقان متزايد', 'عجز عن التحميل'], 'استمر بخطة تحميل تدريجية واطلب تقييماً إذا استمر الألم أو عطل المشي.'),
            'PHYS-31' => $this->arCase('ألم باطن القدم بعد زيادة المشي', 'قد يرتبط الألم بزيادة مفاجئة في حمل المشي على أنسجة باطن القدم، ويحتاج مراقبة موضع الألم واستجابته.', ['بدأ بعد زيادة كمية المشي', 'الألم مرتبط بالتحميل', 'الحذاء والتدرج عاملان مهمان'], ['قلل مدة المشي مؤقتاً', 'استخدم حذاء مريحاً وداعماً'], ['أعد المسافة تدريجياً', 'أضف تمارين بسيطة للقدم وربلة الساق'], ['المشي الطويل رغم ازدياد الألم', 'الأحذية غير المناسبة'], ['ألم عظمي موضّع', 'تورم أو كدمة', 'خدر أو عجز عن التحميل'], 'راقب التحسن بعد خفض الحمل، واطلب تقييماً إذا استمر الألم أو كان موضعياً بشدة.'),
            'PHYS-32' => $this->arCase('ألم وتورم شديدان بالكاحل مع تعذر التحميل', 'انطباع أولي: الإصابة قد تكون كبيرة، ويجب استبعاد الكسر أو الخلع بتقييم طبي عاجل.', ['الألم والتورم شديدان', 'تعذر تحمل الوزن علامة مهمة', 'قد تكون هناك حاجة إلى تصوير عاجل'], ['أوقف التحميل وثبّت الطرف في وضع آمن', 'اطلب رعاية طبية عاجلة الآن'], ['اتبع تعليمات الفريق الطبي بعد التصوير', 'لا تبدأ التأهيل قبل السماح الطبي'], ['المشي على الطرف المصاب', 'محاولة رد أي تشوه أو اختبار الحركة بالقوة'], ['تشوه واضح', 'خدر أو برودة أو تغير لون القدم', 'ألم يتفاقم سريعاً'], 'توجّه إلى الطوارئ أو خدمة رعاية عاجلة اليوم لتقييم الإصابة والتروية والحاجة إلى التصوير.'),
            'PHYS-33' => $this->arCase('ألم جانب الورك عند الاستلقاء', 'الأعراض قد تتوافق مع ألم جانبي بالورك مرتبط بتحميل أوتار الألوية والضغط أثناء الاستلقاء.', ['الألم على الجانب الخارجي للورك', 'الاستلقاء على الجانب يزيد الانزعاج', 'الحمل والضغط الموضعي عاملان مهيجان'], ['تجنب النوم مباشرة على الجانب المؤلم', 'ضع وسادة بين الركبتين عند النوم على الجانب الآخر'], ['ابدأ تقوية تدريجية لعضلات الورك', 'زد المشي حسب التحمل'], ['تقاطع الساقين والضغط الطويل على الورك', 'التمارين الجانبية المؤلمة بشدة'], ['عجز مفاجئ عن التحميل', 'حمى أو احمرار وسخونة', 'ألم شديد بعد سقوط'], 'ابدأ بتخفيف الضغط وإدارة الحمل، واطلب تقييماً إذا استمر الألم أو ازداد.'),
            'PHYS-34' => $this->arCase('ألم مقدمة الورك مع الجري', 'قد يرتبط الألم الأمامي للورك بحمل الجري وحركة الثني المتكرر، ويحتاج فحصاً إذا استمر أو صاحبه قفل.', ['الألم يظهر أثناء الجري أو بعده', 'موضعه في مقدمة الورك', 'السرعة والتلال وطول الخطوة قد تؤثر'], ['خفف الجري المستفز', 'حافظ على حركة مريحة دون ضغط عميق'], ['أعد الجري تدريجياً', 'قوِّ الورك والجذع وفق التحمل'], ['السرعات والتلال المؤلمة', 'الثني العميق المتكرر للورك'], ['قفل أو طقطقة مؤلمة مستمرة', 'ألم ليلي شديد', 'عجز عن التحميل'], 'عدّل الجري واطلب تقييماً إذا استمر الألم أو ظهرت أعراض قفل أو نقص واضح بالحركة.'),
            'PHYS-35' => $this->arCase('ألم وتيبس مزمن بالورك', 'يبدو النمط أقرب إلى ألم مفصلي مزمن قد يرتبط بتغيرات تنكسية، دون إمكان تأكيد ذلك من الأعراض وحدها.', ['تيبس وألم مستمران', 'الوظيفة تتأثر بالمشي أو الحركة', 'القوة والنشاط المتدرج يدعمان الاستقلالية'], ['حافظ على حركة يومية منخفضة التأثير', 'وزع النشاط مع فترات تعافٍ'], ['ابدأ تقوية تدريجية للورك والساق', 'زد المشي أو الدراجة حسب التحمل'], ['الخمول الطويل', 'التحميل المفاجئ العالي'], ['ألم شديد مفاجئ', 'حمى أو تورم واحمرار', 'عجز جديد عن التحميل'], 'ضع خطة نشاط وقوة مع مختص إذا كان الألم يحد الحياة اليومية أو يتفاقم.'),
            'PHYS-36' => $this->arCase('ألم الورك بعد القرفصاء والتدريب', 'قد يرتبط الألم بزيادة حمل التدريب أو عمق القرفصاء بما يتجاوز التحمل الحالي للورك.', ['الأعراض مرتبطة بالقرفصاء والتدريب', 'العمق والحمل يؤثران في الألم', 'تعديل الجرعة والتقنية قد يساعد'], ['قلل العمق أو الوزن إلى مستوى مريح', 'أوقف الحركات التي تسبب ألماً حاداً'], ['أعد الحمل تدريجياً مع تقنية مستقرة', 'قوِّ الورك والجذع ضمن مدى مريح'], ['القرفصاء العميقة المؤلمة', 'محاولات الأوزان القصوى'], ['قفل مؤلم', 'عدم القدرة على التحميل', 'ألم شديد أو تورم بعد إصابة'], 'عدّل التدريب لعدة أيام واطلب تقييماً إذا استمر الألم أو ظهرت أعراض ميكانيكية واضحة.'),
            'PHYS-37' => $this->arCase('ألم شديد بالورك بعد سقوط', 'الإصابة قد ترتبط بكسر أو أذى مهم حول الورك، خصوصاً مع صعوبة تحمل الوزن، وتحتاج تقييماً عاجلاً.', ['السقوط تبعه ألم شديد', 'تحمل الوزن صعب', 'التصوير الطبي قد يكون ضرورياً'], ['تجنب الوقوف أو المشي على الطرف', 'اطلب رعاية طبية عاجلة الآن'], ['اتبع تعليمات الفريق الطبي بعد التقييم', 'ابدأ التأهيل فقط بعد السماح الطبي'], ['اختبار المشي بالقوة', 'تمارين الورك أو التدليك العميق'], ['قصر أو دوران غير طبيعي للساق', 'خدر أو برودة بالطرف', 'دوار أو تدهور عام بعد السقوط'], 'توجّه إلى الطوارئ اليوم لتقييم الورك واستبعاد الكسر؛ التمارين ليست الأولوية في هذه المرحلة.'),
            'PHYS-38' => $this->arCase('ألم وتر أخيل بعد زيادة الجري', 'الأعراض متوافقة مبدئياً مع حساسية وتر أخيل المرتبطة بزيادة حمل الجري، دون تأكيد تشخيصي.', ['الألم مرتبط بزيادة الجري', 'موضعه في وتر أخيل', 'الوتر يستجيب عادة لتحميل تدريجي مناسب'], ['خفف الجري والقفز مؤقتاً', 'حافظ على مشي مريح إن أمكن'], ['ابدأ تمارين تحميل تدريجي لربلة الساق', 'أعد الجري حسب الاستجابة في اليوم التالي'], ['السرعات والتلال المؤلمة', 'التمطيط القسري أو القفز المكثف'], ['فرقعة مفاجئة', 'فقدان القدرة على الدفع بالقدم', 'تورم وكدمة حادان'], 'ابدأ بإدارة الحمل واطلب تقييماً إذا كان الضعف مفاجئاً أو لم يتحسن الألم.'),
            'PHYS-39' => $this->arCase('ألم وتر الرضفة مع القفز', 'قد يرتبط الألم بتحميل وتر الرضفة المتكرر في أنشطة القفز، ويحتاج ضبط الجرعة وبناء القوة تدريجياً.', ['الألم أسفل الرضفة مع القفز', 'الحمل الانفجاري يثير الأعراض', 'قدرة الوتر تتطور بالتدرج لا بالراحة وحدها'], ['خفض عدد القفزات مؤقتاً', 'حافظ على نشاط لا يزيد الأعراض'], ['ابدأ تقوية تدريجية للفخذ والوتر', 'أعد القفز على مراحل'], ['القفز المكثف المتكرر', 'الزيادة المفاجئة في حجم التدريب'], ['فرقعة مع فقدان القدرة على فرد الركبة', 'تورم كبير', 'عجز عن التحميل'], 'عدّل حمل القفز واتبع برنامج قوة، واطلب تقييماً عند استمرار الألم أو وجود ضعف حاد.'),
            'PHYS-40' => $this->arCase('ألم أوتار المرفق مع القبض', 'انطباع أولي: الألم قد يرتبط بتحميل أوتار المرفق والساعد أثناء القبض المتكرر.', ['القبض أو الحمل يثير الألم', 'الأعراض موضعية حول المرفق', 'إدارة الحمل وقوة الساعد مهمتان'], ['خفف قوة وتكرار القبض', 'استخدم أدوات ومقابض أكثر راحة'], ['ابدأ تقوية تدريجية للساعد', 'أعد المهام بجرعات صغيرة'], ['القبض القوي المتكرر', 'التدليك العنيف للمنطقة المؤلمة'], ['ضعف مفاجئ باليد', 'خدر مستمر', 'تورم أو احمرار وسخونة'], 'عدّل الأنشطة واطلب تقييماً إذا استمر الألم أو ترافق بخدر أو ضعف.'),
            'PHYS-41' => $this->arCase('ألم الجانب الخارجي للمرفق لدى لاعب تنس', 'يبدو النمط أقرب إلى ألم أوتار الجانب الخارجي للمرفق المرتبط بحمل المضرب والقبض.', ['ألم خارجي مع القبض أو الضربة الخلفية', 'حجم اللعب والتقنية يؤثران', 'قوة الساعد تحتاج بناء تدريجياً'], ['قلل مدة وشدة اللعب مؤقتاً', 'راجع حجم المقبض وشدة القبضة'], ['قوِّ باسطات الرسغ تدريجياً', 'أعد اللعب على مراحل'], ['اللعب الطويل رغم تصاعد الألم', 'القبضة المشدودة باستمرار'], ['ضعف عصبي متزايد', 'خدر مستمر', 'ألم شديد بعد رض'], 'ابدأ بتعديل حمل اللعب وتقوية الساعد، واستشر مختصاً إذا لم يتحسن الألم.'),
            'PHYS-42' => $this->arCase('ألم حاد بأوتار الفخذ الخلفية أثناء العدو', 'قد ترتبط البداية الحادة أثناء العدو بشد عضلي في أوتار الفخذ الخلفية، وتحتاج تقدير الشدة وظيفياً.', ['ألم مفاجئ أثناء السرعة', 'المشي أو مد الركبة قد يثير الأعراض', 'الكدمة والضعف يساعدان في تقدير الشدة'], ['أوقف العدو واحمِ المنطقة من التمدد المؤلم', 'امشِ فقط ضمن قدرة مريحة'], ['ابدأ حركة وقوة تدريجية', 'عد للعدو بعد استعادة القوة والسرعة تدريجياً'], ['العدو السريع والتمطيط القوي مبكراً', 'التدليك العميق في المرحلة الحادة'], ['كدمة واسعة أو تورم', 'فقدان كبير للقوة', 'عجز عن المشي'], 'رتب تقييماً إذا كان الضعف أو الكدم واضحاً، واتبع تأهيلاً مرحلياً قبل العودة للسرعة.'),
            'PHYS-43' => $this->arCase('شد حاد بعضلات الفخذ أثناء الرياضة', 'الأعراض قد تتوافق مع شد عضلي حاد بالفخذ، ويعتمد التدبير على موضع الإصابة وشدة فقدان الوظيفة.', ['البداية حدثت أثناء نشاط رياضي', 'الألم يتأثر بانقباض أو إطالة العضلة', 'القدرة على المشي مؤشر وظيفي مهم'], ['أوقف النشاط المسبب واحمِ المنطقة', 'حافظ على حركة خفيفة محتملة'], ['زد الحركة والقوة تدريجياً', 'أعد الجري والرياضة على مراحل'], ['الركض أو الركل مبكراً', 'التمطيط القسري في البداية'], ['تشوه أو فجوة بالعضلة', 'كدمة واسعة', 'عجز عن المشي'], 'اطلب تقييماً إذا وُجد ضعف كبير أو كدم واسع، ولا تعد للرياضة قبل استعادة الوظيفة.'),
            'PHYS-44' => $this->arCase('شد ربلة الساق بعد زيادة التدريب', 'قد يرتبط الشد بزيادة الحمل والتعب العضلي، مع ضرورة الانتباه لأعراض غير معتادة قد تشير إلى سبب وعائي.', ['ظهر بعد زيادة التدريب', 'الإحساس بالشد دون إصابة حادة واضحة', 'التعافي والحمل التدريجي مهمان'], ['خفف شدة التدريب واشرب سوائل كافية', 'استخدم حركة لطيفة للكاحل والمشي المريح'], ['أعد تحميل ربلة الساق تدريجياً', 'وازن أيام التدريب والتعافي'], ['السرعات أو القفز مع ألم متزايد', 'التمطيط العنيف'], ['تورم أحادي مفاجئ مع سخونة أو احمرار', 'ضيق نفس أو ألم صدر', 'عجز عن الدفع بالقدم'], 'عدّل التدريب، واطلب تقييماً عاجلاً عند تورم مفاجئ أحادي أو ضيق نفس.'),
            'PHYS-45' => $this->arCase('ألم عضلات الصدر أثناء تمرين الضغط', 'قد يرتبط الألم بتحميل عضلات الصدر أثناء تمرين الضغط، لكن يجب التمييز بين الألم العضلي وأعراض القلب أو التنفس.', ['الألم ظهر أثناء تمرين الصدر', 'الحركة أو الانقباض قد يعيدان الألم العضلي', 'طبيعة الألم والأعراض العامة تحدد الأولوية'], ['أوقف تمرين الضغط حالياً', 'راقب الألم مع التنفس والجهد العام'], ['أعد الحمل تدريجياً فقط إذا كان النمط عضلياً ويتحسن', 'راجع التقنية ومدى الحركة'], ['الضغط الثقيل أو التمدد العميق', 'تجاهل ألم الصدر غير المرتبط بالحركة'], ['ضغط صدري مع ضيق نفس', 'ألم ينتشر للفك أو الذراع', 'تعرق أو دوار أو إغماء'], 'اطلب رعاية عاجلة عند أي أعراض قلبية أو تنفسية؛ وإلا رتّب تقييماً إذا استمر الألم العضلي.'),
            'PHYS-46' => $this->arCase('ألم أسفل الظهر مع ضعف متزايد بالساق', 'الأعراض قد تشير إلى ضغط عصبي خطير، بما في ذلك احتمال تأثر أعصاب ذيل الفرس، وتحتاج تقييماً طبياً عاجلاً دون تأخير.', ['ضعف الساق جديد ويتقدم', 'وجود ألم أسفل الظهر مع تغير عصبي', 'التأخير قد يهدد الوظيفة العصبية'], ['توقف عن التمارين واطلب رعاية طبية عاجلة', 'لا تقد السيارة إذا كانت الساق غير آمنة'], ['اتبع تعليمات قسم الطوارئ أو اختصاصي الأعصاب', 'لا تبدأ التأهيل قبل التقييم الطبي'], ['التمارين أو الرفع', 'انتظار تحسن الضعف من تلقاء نفسه'], ['خدر بمنطقة السرج', 'تغير التحكم بالمثانة أو الأمعاء', 'ضعف سريع أو ثنائي بالساقين'], 'توجّه إلى قسم الطوارئ الآن لإجراء فحص عصبي عاجل؛ الأولوية للتقييم الطبي وليست للتمارين.'),
            'PHYS-47' => $this->arCase('ألم أسفل الظهر مع خدر بمنطقة السرج', 'خدر منطقة السرج مع ألم الظهر علامة خطر قد ترتبط بضغط شديد على أعصاب ذيل الفرس، ويستلزم تقييماً إسعافياً فورياً.', ['خدر في المنطقة بين الفخذين أو حول الأعضاء التناسلية', 'العلامة قد تعكس تأثراً عصبياً مهماً', 'الوقت مهم لحماية الوظيفة العصبية'], ['اتصل بخدمات الطوارئ أو توجّه للطوارئ الآن', 'أوقف أي برنامج تمارين'], ['اتبع التقييم والعلاج الإسعافي', 'لا تؤجل الرعاية بانتظار موعد علاج طبيعي'], ['القيادة منفرداً عند وجود ضعف', 'تجربة تمارين الظهر'], ['احتباس أو سلس البول', 'فقدان التحكم بالأمعاء', 'ضعف الساقين أو فقدان الإحساس المتزايد'], 'اذهب إلى الطوارئ فوراً؛ خدر منطقة السرج يحتاج استبعاد ضغط عصبي إسعافي.'),
            'PHYS-48' => $this->arCase('ألم رقبة شديد مع صداع ودوار بعد إصابة', 'الأعراض بعد الرض قد ترتبط بإصابة مهمة في الرقبة أو الرأس، وتحتاج تقييماً طبياً عاجلاً قبل أي حركة أو تمرين.', ['وجود رض يسبق الأعراض', 'اجتماع ألم الرقبة والصداع والدوار', 'يلزم استبعاد إصابة عصبية أو وعائية أو عظمية'], ['ثبّت الرقبة قدر الإمكان واطلب مساعدة عاجلة', 'تجنب القيادة أو البقاء منفرداً'], ['اتبع تعليمات الطوارئ بعد الفحص', 'لا تبدأ التأهيل قبل السماح الطبي'], ['تحريك أو فرقعة الرقبة', 'التمارين أو التدليك'], ['إغماء أو ارتباك', 'قيء متكرر أو اضطراب رؤية', 'ضعف أو خدر أو صعوبة كلام'], 'توجّه إلى الطوارئ الآن أو اتصل بالإسعاف؛ التقييم الطبي العاجل هو الأولوية.'),
            'PHYS-49' => $this->arCase('إصابة شديدة بالركبة مع تعذر التحميل', 'الألم والتورم الشديدان بعد إصابة كبيرة قد يرتبطان بكسر أو خلع أو إصابة أربطة مهمة، ويحتاجان تقييماً عاجلاً.', ['إصابة كبيرة تلتها أعراض شديدة', 'تعذر تحمل الوزن', 'التورم السريع قد يدل على إصابة داخلية مهمة'], ['أوقف التحميل وثبّت الركبة في وضع مريح', 'اطلب رعاية طبية عاجلة اليوم'], ['اتبع نتيجة التصوير والفحص', 'ابدأ التأهيل فقط بعد استبعاد الإصابة الخطرة'], ['محاولة المشي أو اختبار الثبات', 'رد التشوه ذاتياً أو إجبار الحركة'], ['تشوه واضح', 'برودة أو خدر بالقدم', 'ألم وتورم يتفاقمان سريعاً'], 'اذهب إلى الطوارئ أو الرعاية العاجلة اليوم لتقييم العظام والأربطة والدورة الدموية.'),
            'PHYS-50' => $this->arCase('ألم عضلي هيكلي مع حمى وأعراض عامة', 'اجتماع الألم مع الحمى والمرض العام قد يرتبط بعدوى أو حالة جهازية؛ لا ينبغي اعتباره ألماً عضلياً بسيطاً قبل التقييم الطبي.', ['وجود حمى مع الألم', 'الأعراض العامة تغير مستوى الأولوية', 'التمارين لا تعالج السبب المحتمل في هذه المرحلة'], ['أوقف التمارين واطلب تقييماً طبياً عاجلاً', 'راقب الحرارة والوعي والتنفس دون تأخير الرعاية'], ['اتبع خطة الفريق الطبي بعد تحديد السبب', 'عد للنشاط فقط بعد السماح الطبي'], ['التدريب أو التدليك فوق منطقة حارة ومتورمة', 'إخفاء الحمى بالمسكنات لمواصلة النشاط'], ['ارتباك أو خمول شديد', 'صعوبة تنفس أو طفح منتشر', 'احمرار وسخونة متزايدان أو تدهور سريع'], 'اطلب تقييماً طبياً عاجلاً اليوم، واتصل بالطوارئ إذا كان التدهور سريعاً أو ظهرت صعوبة تنفس أو ارتباك.'),
        ];
    }

    /**
     * @param  list<string>  $findings
     * @param  list<string>  $today
     * @param  list<string>  $nextDays
     * @param  list<string>  $avoid
     * @param  list<string>  $redFlags
     * @return array<string, mixed>
     */
    private function arCase(
        string $title,
        string $impression,
        array $findings,
        array $today,
        array $nextDays,
        array $avoid,
        array $redFlags,
        string $nextStep,
    ): array {
        return [
            'title' => $title,
            'impression' => $impression,
            'findings' => $findings,
            'today' => $today,
            'next_days' => $nextDays,
            'avoid' => $avoid,
            'red_flags' => $redFlags,
            'next_step' => $nextStep,
        ];
    }

    /**
     * @param  list<string>  $findings
     * @return list<array{title: string, detail: string, icon: string}>
     */
    private function arabicFindings(array $findings): array
    {
        $titles = ['النمط السريري', 'العامل المؤثر', 'الأمان والمتابعة', 'الاستجابة للحركة', 'درجة الأعراض'];
        $icons = ['pattern', 'trigger', 'safety', 'recovery', 'severity'];
        $result = [];

        foreach (array_slice($findings, 0, 5) as $index => $detail) {
            $result[] = [
                'title' => $titles[$index],
                'detail' => $detail,
                'icon' => $icons[$index],
            ];
        }

        return $result;
    }

    /**
     * @param  array<string, mixed>  $case
     * @return list<array{title: string, detail: string, icon: string}>
     */
    private function englishFindings(array $case): array
    {
        $findings = $this->stringList($case['key_findings'] ?? []);
        $result = [];

        foreach (array_slice($findings, 0, 5) as $finding) {
            $lower = strtolower($finding);
            [$title, $icon] = match (true) {
                str_contains($lower, 'week'), str_contains($lower, 'day'), str_contains($lower, 'chronic') => ['Duration', 'duration'],
                str_contains($lower, 'weak'), str_contains($lower, 'numb'), str_contains($lower, 'tingl') => ['Neurological feature', 'neuro'],
                str_contains($lower, 'severe'), str_contains($lower, '/10'), str_contains($lower, 'pain') => ['Symptom severity', 'severity'],
                str_contains($lower, 'improv'), str_contains($lower, 'settle'), str_contains($lower, 'recover') => ['Response', 'recovery'],
                str_contains($lower, 'load'), str_contains($lower, 'run'), str_contains($lower, 'train') => ['Load relationship', 'load'],
                str_contains($lower, 'trigger'), str_contains($lower, 'after'), str_contains($lower, 'with') => ['Aggravating factor', 'trigger'],
                default => ['Clinical pattern', 'pattern'],
            };

            $result[] = ['title' => $title, 'detail' => $finding, 'icon' => $icon];
        }

        if (count($result) < 3) {
            $pattern = $this->text($case['expected_clinical_pattern'] ?? null);
            $bodyArea = str_replace('_', ' ', $this->text($case['body_area'] ?? null));
            $supplements = [
                ['title' => 'Clinical pattern', 'detail' => $pattern ?: 'Symptoms require correlation with a clinical examination.', 'icon' => 'pattern'],
                ['title' => 'Body area', 'detail' => $bodyArea !== '' ? ucfirst($bodyArea) : 'Reported musculoskeletal area', 'icon' => 'load'],
                ['title' => 'Safety', 'detail' => 'Monitor for new or worsening warning features.', 'icon' => 'safety'],
            ];
            foreach ($supplements as $supplement) {
                if (count($result) >= 3) {
                    break;
                }
                $result[] = $supplement;
            }
        }

        return $result;
    }

    /**
     * @param  array<string, mixed>  $case
     * @return array<string, mixed>
     */
    private function arabicFallback(array $case): array
    {
        return $this->arCase(
            'تقييم أولي للأعراض العضلية الهيكلية',
            'انطباع أولي: قد ترتبط الأعراض بنمط عضلي هيكلي، وتحتاج ربطها بالفحص السريري قبل تحديد السبب.',
            ['المعلومات الحالية تقدم نمطاً أولياً فقط', 'شدة الأعراض ووظيفتها توجهان المتابعة', 'يجب مراقبة أي تغير جديد أو متفاقم'],
            ['حافظ على نشاط مريح ولا تدفع عبر الألم الحاد', 'راقب تغير الأعراض'],
            ['زد النشاط تدريجياً إذا استقرت الأعراض', 'اطلب تقييماً عند غياب التحسن'],
            ['الحمل الذي يفاقم الأعراض بوضوح', 'تجاهل العلامات الجديدة'],
            ['ضعف أو خدر جديد', 'ألم شديد متفاقم', 'حمى أو تدهور عام'],
            'رتب تقييماً سريرياً إذا استمرت الأعراض أو ساءت.',
        );
    }

    /**
     * @param  mixed  $value
     * @return list<string>
     */
    private function stringList(mixed $value): array
    {
        if (is_string($value)) {
            return $this->sentences($value);
        }

        if (! is_array($value)) {
            return [];
        }

        return array_values(array_filter(array_map(
            fn (mixed $item): string => is_scalar($item) ? trim((string) $item) : '',
            $value,
        ), fn (string $item): bool => $item !== ''));
    }

    /** @return list<string> */
    private function sentences(string $value): array
    {
        $parts = preg_split('/(?<=[.!?])\s+/u', trim($value)) ?: [];

        return array_values(array_filter(array_map(
            fn (string $part): string => rtrim(trim($part), ". \t\n\r\0\x0B"),
            $parts,
        ), fn (string $part): bool => $part !== ''));
    }

    /** @return list<string> */
    private function evidenceCategories(string $evidence): array
    {
        $categories = [];
        $lower = strtolower($evidence);

        if (str_contains($lower, 'apta') || str_contains($lower, 'jospt')) {
            $categories[] = 'APTA/JOSPT clinical practice guidance';
        }
        if (str_contains($lower, 'who')) {
            $categories[] = 'WHO guidance';
        }
        if (str_contains($lower, 'sport')) {
            $categories[] = 'Sports medicine rehabilitation principles';
        }
        if (str_contains($lower, 'orthopaedic') || str_contains($lower, 'musculoskeletal')) {
            $categories[] = 'Orthopaedic and musculoskeletal rehabilitation guidance';
        }
        if (str_contains($lower, 'red flag') || str_contains($lower, 'urgent') || str_contains($lower, 'medical')) {
            $categories[] = 'Clinical safety and red-flag screening guidance';
        }

        $categories[] = 'Evidence-based exercise rehabilitation';

        return array_values(array_unique($categories));
    }

    /** @param array<string, mixed> $case */
    private function englishTitle(array $case): string
    {
        $area = str_replace('_', ' ', $this->text($case['body_area'] ?? null));

        return $area !== '' ? ucfirst($area).' symptom review' : 'Physiotherapy symptom review';
    }

    private function lowerFirst(string $value): string
    {
        return mb_strtolower(mb_substr($value, 0, 1)).mb_substr($value, 1);
    }

    private function text(mixed $value): string
    {
        return is_scalar($value) ? trim((string) $value) : '';
    }
}
